            } else {
                crc &gt;&gt;= 1;
            }
        }
    }
    return crc;
}
</code></pre> <pre><code>def crc16(data: bytes) -&gt; int:
    crc = 0xFFFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc &amp; 0x0001:
                crc = (crc &gt;&gt; 1) ^ 0xA001
            else:
                crc &gt;&gt;= 1
    return crc
</code></pre> <pre><code>// CRC预计算表
static const uint16_t crc16_table[256] = {
    0x0000, 0xC0C1, 0xC181, 0x0140, 0xC301, 0x03C0, 0x0280, 0xC241,
    // ... 完整的256项查表
};

uint16_t crc16_fast(uint8_t *data, uint16_t length) {
    uint16_t crc = 0xFFFF;
    for (uint16_t i = 0; i &lt; length; i++) {
        crc = (crc &gt;&gt; 8) ^ crc16_table[(crc ^ data[i]) &amp; 0xFF];
    }
    return crc;
}
</code></pre>

客户端实现 <pre><code>using Modbus.Device;
using System.Net.Sockets;

public class ModbusTcpClientExample
{
    public ushort[] ReadRegisters(string ip, int port, byte unitId)
    {
        using (TcpClient client = new TcpClient(ip, port))
        {
            var modbusClient = ModbusIpMaster.CreateIp(client);

            // 读取保持寄存器
            ushort[] registers = modbusClient.ReadHoldingRegisters(
                unitId, 0, 10);

            return registers;
        }
    }
}
